//! 🧪️ Real inherited text/image handlers emit shared content or explicit parent mutations and respect resolved locks.
use super::*;
fn inherited(kind:&str)->(LayoutSnapshot,String){let mut document=semio_s_artifact_layout_layout_model::io::text::snapshot::snapshot_wire_codec::default_document();let frame=document.pages[0].frames.iter().find(|frame|frame.kind_str()==kind).unwrap().clone();let id=frame.id().to_string();document.parent_pages[0].layers=document.pages[0].layers.clone();document.parent_pages[0].frames=vec![frame];document.pages[0].frames.clear();document.pages[0].parent_page_id=Some(document.parent_pages[0].id.clone());document.links[0].artifact_kind="s.stdio.pdf".into();document.links[0].artifact_ref="original-pdf".into();(document,id)}
fn dispatch(document:&LayoutSnapshot,id:&str,field:&str,value:&str)->Emit<LayoutMutation,NoConfigMutation>{let config=NoConfig::default();let history=semio_framework_plugin::HistoryView::empty();handle(&PatchFrame{frame_id:id.into(),page_id:Some(document.pages[0].id.clone()),field:field.into(),value:value.into()},&ArtifactView::new(document,&history),&ConfigView{snapshot:&config,window:None}).unwrap()}
#[test]
fn inherited_commands_apply_actual_shared_mutations(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){let(document,id)=inherited(row["kind"].as_str().unwrap());let field=row["field"].as_str().unwrap();let emit=dispatch(&document,&id,field,row["value"].as_str().unwrap());if let Some(effect)=row["effect"].as_str(){let semio_framework::kernel::Effect::ReplayShellCommand{action_id,..}=&emit.effects[0]else{panic!("shared image open")};assert_eq!(action_id,effect);continue}assert_eq!(emit.artifact_mutations.len(),1);let actual=match &emit.artifact_mutations[0]{LayoutMutation::EditStory(edit)=>{let story=document.stories.iter().find(|story|story.id==edit.id).unwrap();let changed:String=story.content.chars().take(edit.offset).chain(edit.insert.chars()).chain(story.content.chars().skip(edit.offset+edit.delete)).collect();assert_eq!(serde_json::to_value(changed).unwrap(),row["value"]);"EditStory"},LayoutMutation::SetStoryRuns(edit)=>{assert_eq!(edit.runs.len(),document.stories.iter().find(|story|story.id==edit.id).unwrap().style_runs.len()+1);"SetStoryRuns"},LayoutMutation::ChangeLinkPath(edit)=>{assert_eq!(serde_json::to_value(&edit.new_path).unwrap(),row["value"]);"ChangeLinkPath"},LayoutMutation::UpdateLink(edit)=>{assert_eq!(edit.width,256);"UpdateLink"},LayoutMutation::SetParentPageContent(edit)=>{if field=="parent.columns"{assert!(matches!(&edit.frames[0],Frame::Text{columns:2,..}))}else{assert_eq!(edit.frames[0].bounds().x,42.0)}"SetParentPageContent"},_=>panic!("unexpected inherited mutation")};assert_eq!(actual,row["mutation"].as_str().unwrap())}}
#[test]
fn inherited_shared_resources_use_instance_flags_and_parent_edits_use_parent_flags(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for row in fixture["locks"].as_array().unwrap(){let(mut document,id)=inherited(row["kind"].as_str().unwrap());match &mut document.parent_pages[0].frames[0]{Frame::Rect{locked,..}|Frame::Text{locked,..}|Frame::Image{locked,..}=>*locked=Some(row["base"].as_bool().unwrap())}document.pages[0].overrides.push(PageOverride{object_id:id.clone(),bounds:None,visible:None,locked:Some(row["instance"].as_bool().unwrap())});let emit=dispatch(&document,&id,row["field"].as_str().unwrap(),row["value"].as_str().unwrap());assert_eq!(emit.artifact_mutations.is_empty(),row["blocked"].as_bool().unwrap())}}
